 CREATE OR REPLACE FUNCTION public.getworkerpopulationreport(p_workerroleid bigint, p_workerpid bigint, p_workerlocation character varying, p_pagesize integer, p_pageoffset integer, p_nolimit boolean)                                                                                                                                                                                                                                                                                                                                                                     
  RETURNS TABLE(reccount bigint, youthsname character varying, youthspid bigint, dob timestamp without time zone, communitydetentionlevel character varying, los character varying, admissiondate date, jurisdiction character varying, region character varying, paroleofficername character varying, hearingtype character varying, charges character varying, parentname character varying, homeaddress character varying, schoolname character varying, youthcontactnumber character varying, parentguardiancontactnumber character varying, memofield character varying)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
      RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 select count(*) over() as reccount,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                         cast(p.firstname||' '||p.lastname as character varying) as youthsname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                         p.cjamspid as youthspid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                         p.dob,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                         rv.description as communitydetentionlevel,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                         cast(age(pl.releasedate,pl.addate) as character varying) as los,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                         pl.addate as admissiondate,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                         isrca.jurisdiction,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                         cast(null as character varying) as region,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                         cast(null as character varying) as paroleofficername,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                         h.description as hearingtype,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                         (select a."name" from allegation a where a.allegationid =isrca.allegationid and a.activeflag = 1) as charges,                                                                                                                                                                                                                                                                                                                                                                                                                                       
                         pgdetail.parentname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                         cast(pa.address||' '||pa.address2 as character varying ) as homeaddress,                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                         s.schoolname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                         cast(pph.phoneextension||'-'||pph.phonenumber as character varying) as youthcontactnumber,                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                         pgdetail.parentguardiancontactnumber,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                         cast(null as character varying) as memofield                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 from placement pl                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 join provider pr on pr.providerid = pl.providerid and pr.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 left join intakeservicerequestcourthearing ich on ich.intakeserviceid = pl.intakeserviceid and ich.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 left join intakeservicerequestcourtaction isrca on isrca.intakeservicerequestcourthearingid  = ich.intakeservicerequestcourthearingid and isrca.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                              
                 join (select distinct actorid ,intakeserviceid from intakeservicerequestactor where activeflag = 1) isra on isra.intakeserviceid = pl.intakeserviceid                                                                                                                                                                                                                                                                                                                                                                                                       
                 join actor a on a.actorid = isra.actorid and a.activeflag = 1 and a.actortype = 'Youth'                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 join person p on p.personid = a.personid and p.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 left join personeducation pe on pe.personid = p.personid and pe.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 left join school s on s.schoolid = pe.schoolid and s.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 left join personphonenumber pph on pph.personid = p.personid and pph.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 left join personaddress pa on pa.personid = p.personid and pa.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 left join (select pisra.intakeserviceid,cast(pp.firstname||' '||pp.lastname as character varying) as parentname,cast(pphone.phoneextension||'-'||pphone.phonenumber as character varying) as parentguardiancontactnumber                                                                                                                                                                                                                                                                                                                                    
                                         from (select distinct actorid ,intakeserviceid from intakeservicerequestactor where activeflag = 1) pisra                                                                                                                                                                                                                                                                                                                                                                                                                           
                                         join actor pa on pa.actorid = pisra.actorid and pa.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                         join (select a.actortype from actortype a where a.activeflag = 1 and (upper(a.typedescription) like '%GUARDIAN%' or upper(a.typedescription) like '%PARENT%') )actype on actype.actortype = pa.actortype                                                                                                                                                                                                                                                                                                                            
                                         join person pp on pp.personid = pa.personid and pp.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                         left join personphonenumber pphone on pphone.personid = pp.personid and pphone.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                         )pgdetail on pgdetail.intakeserviceid = pl.intakeserviceid                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 join userprofile up on up.securityusersid = pl.updatedby and up.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 join muser m on m.securityusersid = up.securityusersid  and m.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 join rolemapping rm  on cast(m.id as character varying) = rm.principalid  and rm.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 join role r on r.id = rm.roleid and r.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 join userprofileaddress upa on upa.securityusersid = up.securityusersid and upa.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 left join referencevalues rv on rv.ref_key = pr.providerunit                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 left join hearingtype h on h.hearingtypekey = ich.hearingtypekey                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 where pl.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 and case when p_workerroleid is not null then r.id = p_workerroleid else r.id in ('2450','69') end                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 and case when p_workerpid is not null then up.cjamspid = p_workerpid else true end                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 and case when p_workerlocation is not null then upa.city ilike '%'||p_workerlocation||'%' else true end                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 limit (case when p_nolimit is false then p_pagesize else null end ) offset (case when p_nolimit is false then p_pageoffset else null end);                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  

